'use strict';
(()=>{
const payload=window.ATLAS_POINTS,records=payload.points;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let nodes=new Map(),navigate=()=>{},current=null,currentTopic=null,last='',trail=[],showAllNext=false,moving=false;
const names=new Map(window.ATLAS_DATA.map(t=>[t.slug,t.name]));
const get=id=>nodes.get(id),model=id=>records[id];
const parents=n=>{const p=[];while(n){p.unshift(n);n=n.parent;}return p;};
function label(id){return get(id)?.name||'未找到知识点';}
function button(id,extra='',cls=''){const n=get(id);return `<button class="point-link ${cls}" data-point="${esc(id)}"><span>${esc(n?.name||'')}</span>${extra}<small>${esc(names.get(n?.topic.slug)||'')}</small></button>`;}
function detailLink(id){return button(id,'','small-point');}
function following(id){return [...nodes.values()].filter(n=>model(n.pid)?.requires.some(d=>(d.anyOf||[d.id]).includes(id)));}
function dependencyGroup(d,index){return `<div class="point-dependency ${d.anyOf?'one-of':''}"><div class="point-dependency-label"><span>${d.anyOf?'任选一项':'先修 '+(index+1)}</span><span>${esc(d.depth)}${d.scope?' · '+esc(d.scope):''}</span></div>${(d.anyOf||[d.id]).map(id=>button(id)).join('')}<p>${esc(d.reason)}</p></div>`;}
function plan(id){const seen=new Map(),choices=new Set(),out=[],rank=['认识','理解','会用','能实现'];function visit(pid){for(const d of model(pid)?.requires||[]){if(d.anyOf){const key=[...d.anyOf].sort().join(',');if(!choices.has(key)){choices.add(key);out.push({choice:d});}continue;}const prior=seen.get(d.id);if(prior){if(rank.indexOf(d.depth)>rank.indexOf(prior.depth))prior.depth=d.depth;if(!d.scope)delete prior.scope;continue;}const step={id:d.id,depth:d.depth,scope:d.scope};seen.set(d.id,step);visit(d.id);out.push(step);}}visit(id);return out;}
function planHtml(id){const steps=plan(id);return `<ol class="point-plan">${steps.map(s=>s.choice?`<li class="plan-choice"><span class="plan-marker">择</span><div><p>选一条入口；点击可查看该入口自己的前置</p><div class="plan-options">${s.choice.anyOf.map(detailLink).join('')}</div></div></li>`:`<li><span class="plan-marker"></span><div>${detailLink(s.id)}<small>达到：${esc(s.depth)}${s.scope?' · '+esc(s.scope):''}</small></div></li>`).join('')}<li class="plan-target"><span class="plan-marker">✓</span><div><strong>${esc(label(id))}</strong><p>前面的必要基础具备后，学习当前知识点。</p></div></li></ol>`;}
function bind(box){box.querySelectorAll('[data-point]').forEach(b=>b.onclick=()=>go(b.dataset.point));box.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>(()=>{trail=[];navigate(null,b.dataset.topic);})());const back=box.querySelector('#point-history-back');if(back)back.onclick=()=>{const id=trail.pop();if(id){last='';moving=true;try{navigate(get(id));}finally{moving=false;}}};const next=box.querySelector('#point-more-next');if(next)next.onclick=()=>{showAllNext=!showAllNext;last='';render(currentTopic,current);};}
function go(id){if(!get(id))return;if(current?.pid&&id!==current.pid)trail.push(current.pid);showAllNext=false;moving=true;try{navigate(get(id));}finally{moving=false;}}
function browse(topic,node){const scope=node||topic,all=[...nodes.values()].filter(n=>n.topic===topic&&n.depth>=3);const root=topic.slug==='overview';
 if(root)return `<header class="point-intro"><small>计算机学习图谱</small><h1>从一个知识点开始</h1><p>选方向，再选知识点。每次只看它的先修、建议补充和后续，不必展开整张大图。</p></header><div class="point-directions">${window.ATLAS_DATA.map(t=>`<button data-topic="${esc(t.slug)}"><strong>${esc(t.name)}</strong><span>进入知识目录 →</span></button>`).join('')}</div>`;
 const stages=scope.depth===0?scope.children:scope.depth===1?[scope]:[{name:scope.name,children:scope.depth===2?[scope]:scope.children}];
 return `<header class="point-intro"><small>知识目录 · ${esc(names.get(topic.slug))}</small><h1>${esc(scope.name)}</h1><p>点一个具体知识点，查看它自己的依赖。目录分组不算先修。</p></header><label class="point-filter-label">查找本方向知识点<input id="point-filter" type="search" placeholder="输入知识点名称，例如 TLS、队列、梯度…" autocomplete="off"></label><div id="point-filter-results" hidden></div><div id="point-directory">${stages.map(stage=>`<section class="point-directory-stage"><h2>${esc(stage.name)}</h2><div class="point-module-grid">${stage.children.map(module=>`<section class="point-module"><h3>${esc(module.name)}</h3><div>${(module.depth<3?module.children:[module]).map(n=>button(n.pid)).join('')}</div></section>`).join('')}</div></section>`).join('')}</div>`;
}
function knowledge(topic,n){const r=model(n.pid),next=following(n.pid),children=n.children.filter(x=>model(x.pid)),isCategory=r?.kind==='category',steps=plan(n.pid),scope=parents(n).slice(0,-1);
 if(isCategory)return `<header class="point-intro"><small>分类目录</small><h1>${esc(n.name)}</h1><p>这个节点用于整理子主题，本身不作为先修要求。请选择下面一个具体知识点。</p></header><div class="point-category-children">${children.map(x=>button(x.pid)).join('')}</div>`;
 const after=showAllNext?next:next.slice(0,5);
 return `<header class="point-focus-header"><div class="point-breadcrumb">${scope.map(x=>`<button data-point="${esc(x.pid)}">${esc(x.name)}</button>`).join('<span>›</span>')}</div><div class="point-focus-heading"><div><small>当前知识点</small><h1>${esc(n.name)}</h1></div><div class="point-focus-actions">${trail.length?'<button id="point-history-back">← 上一个知识点</button>':''}<button data-topic="${esc(topic.slug)}">返回目录</button></div></div><p class="point-current-note">${esc(r.note||'按下面的必要前置补基础；建议补充不影响开始学习。')}</p></header>
 <div class="point-local-graph" aria-label="当前知识点的局部依赖关系">
 <section class="point-prior-column"><h2>先修知识 <span>${r.requires.length} 项</span></h2>${r.requires.length?r.requires.map(dependencyGroup).join(''):'<div class="point-zero"><strong>可以从这里开始</strong><p>没有登记必须先学的知识点。先结合一个简单例子建立概念。</p></div>'}</section>
 <div class="point-flow-arrow" aria-hidden="true">→</div>
 <section class="point-now-column"><h2>现在学</h2><div class="point-now-card"><small>${esc(names.get(topic.slug))}</small><strong>${esc(n.name)}</strong><span>补齐必要基础后开始</span></div>${children.length?`<details class="point-refine"><summary>继续细分 · ${children.length} 个子点</summary>${children.map(x=>button(x.pid)).join('')}</details>`:''}</section>
 <div class="point-flow-arrow" aria-hidden="true">→</div>
 <section class="point-next-column"><h2>学完可继续 <span>${next.length} 项</span></h2><p class="point-column-note">这些知识点会用到当前概念，按目标选择。</p>${after.map(x=>button(x.pid)).join('')}${next.length>5?`<button id="point-more-next" class="point-more">${showAllNext?'收起':'查看其余 '+(next.length-5)+' 项'}</button>`:''}${!next.length?'<p class="point-zero">暂未登记直接后续；可返回目录选择其他主题。</p>':''}</section></div>
 <section class="point-order-section"><div><h2>到这个知识点的学习顺序</h2><p>按依赖关系从前往后学，已掌握的可以跳过；互不依赖的点可并行。任选入口只需选一条。</p></div><details class="point-plan-detail" ${steps.length<=5?'open':''}><summary>${steps.length?`展开 ${steps.length} 项前置安排`:'从当前知识点开始'}</summary>${planHtml(n.pid)}</details></section>
 ${(r.recommended||[]).length?`<details class="point-recommended"><summary>建议补充 · 非必修（${r.recommended.length} 项）</summary><div class="point-recommend-grid">${r.recommended.map(d=>`<div>${button(d.id)}<p>${esc(d.reason)}</p></div>`).join('')}</div></details>`:''}
 <p class="point-footer-note">程度说明：认识＝能辨认术语；理解＝能说明关系与适用条件；会用＝能独立完成小例子；能实现＝能写出核心过程并验证。<br>箭头表示学习前置，不表示目录层级。具体概念的入门要求与其所有细项分开，避免把整门课变成门槛。</p>`;
}
function render(topic,n){if(!moving&&!n&&topic!==currentTopic)trail=[];const key=topic.slug+'|'+(n?.pid||'')+'|'+showAllNext;if(key===last)return;last=key;current=n;currentTopic=topic;const box=document.getElementById('point-explorer');box.innerHTML=n?.depth>=3&&model(n.pid)?knowledge(topic,n):browse(topic,n);box.scrollTop=0;bind(box);
 const filter=box.querySelector('#point-filter');if(filter)filter.oninput=()=>{const q=filter.value.trim().toLowerCase(),found=[...nodes.values()].filter(x=>x.topic===topic&&x.depth>=3&&x.name.toLowerCase().includes(q));const results=box.querySelector('#point-filter-results');results.hidden=!q;box.querySelector('#point-directory').hidden=!!q;if(q){results.innerHTML=`<p class="point-search-count">找到 ${found.length} 项${found.length>100?'，显示前 100 项':''}</p><div class="point-search-grid">${found.slice(0,100).map(x=>button(x.pid,`<em>${esc(parents(x).slice(2,-1).map(p=>p.name).join(' / '))}</em>`)).join('')}</div>`;bind(results);}};
}
window.PointExplorer={init(all,fn){navigate=fn;let i=0;for(const n of all){if(n.topic.slug==='overview')continue;n.pid=payload.ids[i++];nodes.set(n.pid,n);}if(i!==payload.ids.length)throw Error('Point catalog does not match knowledge tree');},render,reset(){last='';showAllNext=false;},getNode:get};
})();
